#include <gtest/gtest.h>
#include <yoga/Yoga.h>
#include "../util/TestUtil.h"

TEST(YogaTest, complex_mixed_spanning_alignment) {
  YGConfigRef config = YGConfigNew();

  YGNodeRef root = YGNodeNewWithConfig(config);
  YGNodeStyleSetPositionType(root, YGPositionTypeAbsolute);
  YGNodeStyleSetDisplay(root, YGDisplayGrid);
  YGNodeStyleSetGridTemplateColumnsCount(root, 4);
  YGNodeStyleSetGridTemplateColumn(root, 0, YGGridTrackTypePoints, 100);
  YGNodeStyleSetGridTemplateColumn(root, 1, YGGridTrackTypeAuto, 0);
  YGNodeStyleSetGridTemplateColumn(root, 2, YGGridTrackTypeFr, 1);
  YGNodeStyleSetGridTemplateColumn(root, 3, YGGridTrackTypeFr, 2);
  YGNodeStyleSetGridTemplateRowsCount(root, 3);
  YGNodeStyleSetGridTemplateRow(root, 0, YGGridTrackTypePoints, 80);
  YGNodeStyleSetGridTemplateRow(root, 1, YGGridTrackTypeAuto, 0);
  YGNodeStyleSetGridTemplateRow(root, 2, YGGridTrackTypeFr, 1);
  YGNodeStyleSetWidth(root, 600);
  YGNodeStyleSetHeight(root, 400);
  YGNodeStyleSetGap(root, YGGutterAll, 10);
  YGNodeStyleSetJustifyContent(root, YGJustifySpaceBetween);
  YGNodeStyleSetAlignContent(root, YGAlignCenter);

  YGNodeRef root_child0 = YGNodeNewWithConfig(config);
  YGNodeStyleSetWidth(root_child0, 250);
  YGNodeStyleSetHeightPercent(root_child0, 100);
  YGNodeStyleSetGridColumnStart(root_child0, 1);
  YGNodeStyleSetGridColumnEnd(root_child0, 3);
  YGNodeStyleSetJustifySelf(root_child0, YGJustifyEnd);
  YGNodeInsertChild(root, root_child0, 0);

  YGNodeRef root_child1 = YGNodeNewWithConfig(config);
  YGNodeStyleSetWidthPercent(root_child1, 100);
  YGNodeStyleSetHeight(root_child1, 80);
  YGNodeStyleSetAlignSelf(root_child1, YGAlignCenter);
  YGNodeInsertChild(root, root_child1, 1);

  YGNodeRef root_child2 = YGNodeNewWithConfig(config);
  YGNodeStyleSetWidthPercent(root_child2, 100);
  YGNodeStyleSetHeight(root_child2, 200);
  YGNodeStyleSetGridRowStart(root_child2, 2);
  YGNodeStyleSetGridRowEnd(root_child2, 4);
  YGNodeInsertChild(root, root_child2, 2);
  YGNodeCalculateLayout(root, YGUndefined, YGUndefined, YGDirectionLTR);

  ASSERT_FLOAT_EQ(0, YGNodeLayoutGetLeft(root));
  ASSERT_FLOAT_EQ(0, YGNodeLayoutGetTop(root));
  ASSERT_FLOAT_EQ(600, YGNodeLayoutGetWidth(root));
  ASSERT_FLOAT_EQ(400, YGNodeLayoutGetHeight(root));

  ASSERT_FLOAT_EQ(0, YGNodeLayoutGetLeft(root_child0));
  ASSERT_FLOAT_EQ(0, YGNodeLayoutGetTop(root_child0));
  ASSERT_FLOAT_EQ(250, YGNodeLayoutGetWidth(root_child0));
  ASSERT_FLOAT_EQ(80, YGNodeLayoutGetHeight(root_child0));

  ASSERT_FLOAT_EQ(260, YGNodeLayoutGetLeft(root_child1));
  ASSERT_FLOAT_EQ(0, YGNodeLayoutGetTop(root_child1));
  ASSERT_FLOAT_EQ(110, YGNodeLayoutGetWidth(root_child1));
  ASSERT_FLOAT_EQ(80, YGNodeLayoutGetHeight(root_child1));

  ASSERT_FLOAT_EQ(0, YGNodeLayoutGetLeft(root_child2));
  ASSERT_FLOAT_EQ(90, YGNodeLayoutGetTop(root_child2));
  ASSERT_FLOAT_EQ(100, YGNodeLayoutGetWidth(root_child2));
  ASSERT_FLOAT_EQ(200, YGNodeLayoutGetHeight(root_child2));

  YGNodeCalculateLayout(root, YGUndefined, YGUndefined, YGDirectionRTL);

  ASSERT_FLOAT_EQ(0, YGNodeLayoutGetLeft(root));
  ASSERT_FLOAT_EQ(0, YGNodeLayoutGetTop(root));
  ASSERT_FLOAT_EQ(600, YGNodeLayoutGetWidth(root));
  ASSERT_FLOAT_EQ(400, YGNodeLayoutGetHeight(root));

  ASSERT_FLOAT_EQ(350, YGNodeLayoutGetLeft(root_child0));
  ASSERT_FLOAT_EQ(0, YGNodeLayoutGetTop(root_child0));
  ASSERT_FLOAT_EQ(250, YGNodeLayoutGetWidth(root_child0));
  ASSERT_FLOAT_EQ(80, YGNodeLayoutGetHeight(root_child0));

  ASSERT_FLOAT_EQ(230, YGNodeLayoutGetLeft(root_child1));
  ASSERT_FLOAT_EQ(0, YGNodeLayoutGetTop(root_child1));
  ASSERT_FLOAT_EQ(110, YGNodeLayoutGetWidth(root_child1));
  ASSERT_FLOAT_EQ(80, YGNodeLayoutGetHeight(root_child1));

  ASSERT_FLOAT_EQ(500, YGNodeLayoutGetLeft(root_child2));
  ASSERT_FLOAT_EQ(90, YGNodeLayoutGetTop(root_child2));
  ASSERT_FLOAT_EQ(100, YGNodeLayoutGetWidth(root_child2));
  ASSERT_FLOAT_EQ(200, YGNodeLayoutGetHeight(root_child2));

  YGNodeFreeRecursive(root);

  YGConfigFree(config);
}
